536	func (e *recordingEnqueuer) Enqueue(task *asynq.Task, _ ...asynq.Option) (*asynq.TaskInfo, error) {
537		if e.err != nil {
538			return nil, e.err
539		}
540		switch task.Type() {
541		case queue.TypeWorkspaceSync:
542			var payload queue.WorkspaceSyncPayload
543			if err := json.Unmarshal(task.Payload(), &payload); err != nil {
544				return nil, err
545			}
546			e.workspaceSyncs = append(e.workspaceSyncs, payload)
547		case queue.TypeTaskSync:
548			var payload queue.TaskSyncPayload
549			if err := json.Unmarshal(task.Payload(), &payload); err != nil {
550				return nil, err
551			}
552			e.taskSyncs = append(e.taskSyncs, payload)
553		}
554		return &asynq.TaskInfo{ID: "task-id", Queue: queue.QueueDefault, Type: task.Type()}, nil
555	}
