599		for i := range dest {
600			switch d := dest[i].(type) {
601			case *pgtype.UUID:
602				v, ok := values[i].(pgtype.UUID)
603				if !ok {
604					return fmt.Errorf("values[%d]: expected pgtype.UUID, got %T", i, values[i])
605				}
606				*d = v
607			case *string:
608				v, ok := values[i].(string)
609				if !ok {
610					return fmt.Errorf("values[%d]: expected string, got %T", i, values[i])
611				}
612				*d = v
613			case **string:
614				v, ok := values[i].(*string)
615				if !ok {
616					return fmt.Errorf("values[%d]: expected *string, got %T", i, values[i])
617				}
618				*d = v
619			case *pgtype.Timestamptz:
620				v, ok := values[i].(pgtype.Timestamptz)
621				if !ok {
622					return fmt.Errorf("values[%d]: expected pgtype.Timestamptz, got %T", i, values[i])
623				}
624				*d = v
625			default:
626				return fmt.Errorf("unsupported scan destination %T", dest[i])
627			}
628		}
629		return nil
630	}
